            payload = base64.b64decode(str(req.get("b64") or ""))
            self.write_port(payload)
            return {"ok": True, "len": len(payload)}
        if op == "attach":
            replay = int(req.get("replay") or 0)
            if replay > 0:
                history = self.rx_snapshot()[-replay:]
                if history:
                    try:
                        conn.sendall(
                            (
                                json.dumps(
                                    {
                                        "ev": "rx",
                                        "b64": base64.b64encode(history).decode(
                                            "ascii"
                                        ),
                                        "replay": len(history),
                                    },
                                    ensure_ascii=False,
                                )
                                + "\n"
                            ).encode("utf-8")

