    if (s_ctx.pwr_long_fired) {
        return;
    }

    if (lv_tick_elaps(s_ctx.pwr_press_tick) >= LV_PORT_PWR_LONG_MS) {
        s_ctx.pwr_long_fired = true;
        helm_pwr_on_long();
        BTN_LOG("PWR long 2s");
    }
}

