static void elev_canvas_paint(lv_obj_t *cv, int w, int h, bool grid)
{
    lv_layer_t layer;
    double mn = s_elev[0];
    double mx = s_elev[0];
    const int base = h - 1;
    const int top = grid ? 10 : 3;
    const int bot = base - top;

    for (int i = 1; i < ELEV_PROF_N; i++) {
        if (s_elev[i] < mn) mn = s_elev[i];
        if (s_elev[i] > mx) mx = s_elev[i];
    }
    if (mx - mn < 1.0) {
        mx = mn + 1.0;
    }

    lv_canvas_fill_bg(cv, lv_color_hex(P_PAPER), LV_OPA_COVER);
    lv_canvas_init_layer(cv, &layer);
    if (grid) {
        lv_draw_line_dsc_t gd;

        lv_draw_line_dsc_init(&gd);
        gd.color = lv_color_hex(P_CARD);
        gd.width = 1;
        gd.opa = LV_OPA_COVER;
        for (int k = 1; k <= 3; k++) {
            gd.p1.x = 0;
            gd.p1.y = top + (bot - top) * k / 4;
            gd.p2.x = w - 1;
            gd.p2.y = gd.p1.y;
            lv_draw_line(&layer, &gd);
        }
    }
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        const int x1 = (i * (w - 1)) / (ELEV_PROF_N - 1);
        const int x2 = ((i + 1) * (w - 1)) / (ELEV_PROF_N - 1);
        const int y1 = bot - (int)lround((s_elev[i] - mn) / (mx - mn) *
                                        (double)(bot - top));
        const int y2 = bot - (int)lround((s_elev[i + 1] - mn) / (mx - mn) *
                                         (double)(bot - top));
        const uint32_t fill = elev_fill(s_elev_zone[i]);
        const uint32_t ink = elev_ink(s_elev_zone[i]);
        lv_draw_triangle_dsc_t tri;
        lv_draw_line_dsc_t ld;

        lv_draw_triangle_dsc_init(&tri);
        tri.color = lv_color_hex(fill);
        tri.opa = LV_OPA_COVER;
        tri.grad.dir = LV_GRAD_DIR_NONE;
        tri.p[0].x = x1;
        tri.p[0].y = y1;
        tri.p[1].x = x2;
        tri.p[1].y = y2;
        tri.p[2].x = x2;
        tri.p[2].y = base;
        lv_draw_triangle(&layer, &tri);
        tri.p[0].x = x2;
        tri.p[0].y = base;
        tri.p[1].x = x1;
        tri.p[1].y = base;
        tri.p[2].x = x1;
        tri.p[2].y = y1;
        lv_draw_triangle(&layer, &tri);

        lv_draw_line_dsc_init(&ld);
        ld.color = lv_color_hex(ink);
        ld.width = 2;
        ld.opa = LV_OPA_COVER;
        ld.round_start = 1;
        ld.round_end = 1;
        ld.p1.x = x1;
        ld.p1.y = y1;
        ld.p2.x = x2;
        ld.p2.y = y2;
        lv_draw_line(&layer, &ld);
    }
    lv_canvas_finish_layer(cv, &layer);
}

