 */
static int sb_right_layout(bool rec, bool nav, int txt_ink_x0, int pos[3])
{
    int x;
    int left;

    pos[2] = txt_ink_x0 - (SB_INK_GAP_BAT_TXT + s_slot[SB_BAT].ink_w);
    left = pos[2];
    /* x = 紧邻左侧那一项的**右边界（不含）**；NAV 隐藏时 REC 直接用
     * “NAV→电量 8” 的间隙贴到电量左边（模拟器 right_layout 同一规则）。 */
    x = pos[2] - SB_INK_GAP_NAV_BAT;
    pos[1] = nav ? (x - s_slot[SB_NAV].ink_w) : -1;
    if (nav) {
        left = pos[1];
        x = pos[1] - SB_INK_GAP_REC_NAV;
    }
    pos[0] = rec ? (x - SB_REC_D) : -1;
    if (rec) {
        left = pos[0];
    }
    return left;
}

