/**
 * @brief 按墨迹规则排两簇；碰撞时按 踏频→功率→NAV→BLE 依次隐藏。
 *
 * @details 布局只依赖「时间宽度、电量文字宽度、六个可隐藏项是否在」——
 *          这些都没变的 1 s 拍直接跳过，不碰对象位置。
 */
static void sb_layout(int time_ink_w, int batt_ink_w, bool ble, bool hr,
                      bool pwr, bool cad, bool rec, bool nav)
{
    const uint32_t key = sb_layout_make_key(time_ink_w, batt_ink_w, ble, hr,
                                            pwr, cad, rec, nav);
    const int x0 = SB_TIME_X + time_ink_w + SB_INK_GAP_TIME;   /* 时间墨迹 x1+1+8 */
    const int txt_ink_x0 = SB_BATT_INK_RIGHT - batt_ink_w + 1;
    int pos[5];
    int rpos[3];
    int left_end;
    int right_left;

    if (s_has_layout && key == s_layout_key) {
        return;
    }
    s_layout_key = key;
    s_has_layout = true;

    for (int guard = 0; guard < 5; guard++) {
        left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
        right_left = sb_right_layout(rec, nav, txt_ink_x0, rpos);
        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
            break;
        }
        if (cad) {
            cad = false;
        } else if (pwr) {
            pwr = false;
        } else if (nav) {
            nav = false;
        } else if (ble) {
            ble = false;
        } else {
            break;
        }
    }

    left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
    right_left = sb_right_layout(rec, nav, txt_ink_x0, rpos);
    (void)left_end;
    (void)right_left;

    for (int i = 0; i < 5; i++) {
        s_ink_x[i] = pos[i];
        s_shown[i] = (pos[i] >= 0);
    }
    s_ink_x[SB_NAV] = rpos[1];
    s_shown[SB_NAV] = (rpos[1] >= 0);
    s_ink_x[SB_BAT] = rpos[2];
    s_shown[SB_BAT] = (rpos[2] >= 0);
    s_rec_x = rpos[0];

    for (int k = 0; k < SB_SLOT_N; k++) {
        if (s_shown[k]) {
            sb_slot_place(k);
        }
    }
}

