{
    sb_slot_t * s = &s_slot[k];

    if (s->ico == NULL) {
        return;
    }

    if (!shown || tone == SB_TONE_HIDE) {
        if (s->vis_last || !lv_obj_has_flag(s->ico, LV_OBJ_FLAG_HIDDEN)) {
            sb_hide(s->ico);
