/** @brief 页头左侧强调条（4px 橙，整条高度）。
 *  @details 页头不再铺整条色带（用户嫌丑）：颜色只靠这条**形状**承载，
 *           标题走大字号黑字。半透半反屏会把淡色洗白，实心色带本来也立不住。
 */
static void helm_mhead_accent(lv_obj_t * head)
{
    lv_obj_t * rail = lv_obj_create(head);

    lv_obj_remove_style_all(rail);
    lv_obj_set_size(rail, 4, HELM_MHEAD_H);
    lv_obj_add_flag(rail, LV_OBJ_FLAG_FLOATING);
    lv_obj_align(rail, LV_ALIGN_LEFT_MID, 0, 0);
    lv_obj_set_style_bg_opa(rail, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(rail, helm_color(HELM_COLOR_NAV), 0);
    lv_obj_clear_flag(rail, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(rail, LV_OBJ_FLAG_SCROLLABLE);
}

/** @brief 页头的通用样式（create / 换主题重设 两处同源）。
 *  @details 透明底（露出页面底色）+ 4px 橙左轨 + 底部发丝线；标题 INK。
 */
static void helm_mhead_style(lv_obj_t * head)
{
    lv_obj_set_style_bg_opa(head, LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_hor(head, 16, 0);
    lv_obj_set_style_border_side(head, LV_BORDER_SIDE_BOTTOM, 0);
    lv_obj_set_style_border_width(head, 1, 0);
    lv_obj_set_style_border_color(head, helm_color(HELM_COLOR_HAIR), 0);
    if (lv_obj_get_child_count(head) > 0) {
        lv_obj_t * rail = lv_obj_get_child(head, 0);

        if (rail != NULL && lv_obj_get_width(rail) <= 4) {
            lv_obj_set_size(rail, 4, HELM_MHEAD_H);
            lv_obj_set_style_bg_color(rail, helm_color(HELM_COLOR_NAV), 0);
        }
    }
}

lv_obj_t * helm_mhead_create(lv_obj_t * parent, const char * title)
