    VMAP_TONE(water_r, water_g, water_b, VMAP_DAY_DEEPEN_PCT);
    VMAP_TONE(road_case_r, road_case_g, road_case_b, VMAP_DAY_DEEPEN_PCT);
    VMAP_TONE(waterway_r, waterway_g, waterway_b, VMAP_DAY_DEEPEN_PCT);
