```c
/** @brief 表盘底部剖面：**前视 3 km 窗口**（导航）或**最近 10 分钟**（记录）。
 *
 * 2026-11-01 用户："和老版本的海拔折线图一样，慢慢的移动，直到以一定距离刷新一次"：
 *   · 导航态改成只采"当前位置 → 前方 3 km"，窗口按**距离**（每 20 m）平移重烘，
 *     不再把整条剩余路线压成 60 点（长 GPX 时每个点 1~2 km，看着不动）；
 *   · 记录态 10 s 一个采样点，缓冲满后每来一点平移 1/60 屏；
 *   · 左边那根 4px 竖条（`dial_elev_cur`）删掉 —— 窗口语义已经说明"现在"在哪
 *     （导航 = 左端，记录 = 右端），那根线只会让人问"这是什么"。
 */
static void helm_dial_elev_tick(const bicycle_runtime_t * rt)
{
    bool nav = helm_nav_on();
    uint32_t step_cm = 0u;
    uint32_t sig = 0u;
    uint8_t wn = 0u;
    char lab[32];

    if (nav) {
#if VMAP_ROUTE_ENABLE
        double along = map_page_nav_along_m(s_sh.map);
        double total = map_page_nav_total_m(s_sh.map);
        double span = HELM_DIAL_NAV_SPAN_M;

        if (total > 0.0 && along + span > total) {
            span = total - along;
        }
        if (span > 0.0) {
            wn = (uint8_t)map_page_nav_profile_span(s_sh.map, along, span,
                                                    s_dial_win,
                                                    HELM_CLIMB_PROF_N);
        }
        if (wn >= 2u) {
            step_cm = (uint32_t)(span * 100.0 / (double)(wn - 1u));
            if (step_cm < 1u) {
                step_cm = 1u;
            }
        }
        /* 每前进 20 m 重烘一次（3 km 窗 × 190 px ⇒ 20 m ≈ 1.3 px，够连续）。 */
        sig = 0x40000000u | (uint32_t)(along / 20.0);
        if (total > 0.0) {
            double remain = total - along;

            lv_snprintf(lab, sizeof(lab), "前方 %.1f km",
                        (remain > 0.0) ? remain : 0.0);
        } else {
            lv_snprintf(lab, sizeof(lab), "前方 -- km");
        }
#endif
    } else if (helm_riding() && s_rec_ele_n >= 2u) {
        wn = s_rec_ele_n;
        memcpy(s_dial_win, s_rec_ele, (size_t)wn * sizeof(s_dial_win[0]));
        if (rt != NULL && rt->session_distance_m > 1.0) {
            step_cm = (uint32_t)(rt->session_distance_m * 100.0 /
                                 (double)(wn - 1u));
        }
        if (step_cm < 100u) {
            step_cm = 0u;      /* <1 m/点：坡度不可信，保持灰 */
        }
        sig = 0x80000000u | ((uint32_t)s_rec_ele_slot << 1) |
              ((s_rec_ele_n < HELM_CLIMB_PROF_N) ? 1u : 0u);
        {
            unsigned mins = (unsigned)(((uint32_t)(wn - 1u) *
                (uint32_t)(HELM_CLIMB_REC_PERIOD_MS / 1000u) + 59u) / 60u);

            if (mins < 1u) {
                mins = 1u;
            }
            lv_snprintf(lab, sizeof(lab), "近 %u 分钟", mins);
        }
    }

    if (wn < 2u) {
        if (s_dial_prof_valid) {
            s_dial_prof_valid = false;
            if (s_sh.dial_elev_cv != NULL) {
                lv_obj_add_flag(s_sh.dial_elev_cv, LV_OBJ_FLAG_HIDDEN);
            }
        }
        helm_label_set(s_sh.dial_elev_lab, "--");
        helm_show(s_sh.dial_elev_lab, false);
        helm_dial_ph_update(rt, true);
        s_dial_run_n = 0;
        s_dial_run_min = 0;
        return;
    }

    if (!s_dial_prof_valid || s_dial_prof_sig != sig) {
        helm_dial_elev_paint(s_dial_win, wn, step_cm);
        s_dial_prof_valid = true;
        s_dial_prof_sig = sig;
    }

    helm_label_set(s_sh.dial_elev_lab, lab);
    helm_show(s_sh.dial_ph_card, false);
    helm_show(s_sh.dial_elev_lab, true);
    if (s_sh.dial_elev_cv != NULL) {
        lv_obj_remove_flag(s_sh.dial_elev_cv, LV_OBJ_FLAG_HIDDEN);
    }
}
