 */
#define HELM_IBEAM_W    10
#define HELM_IBEAM_H    12
#define HELM_IBEAM_CAP   3
#define HELM_IBEAM_STEM  2

static lv_obj_t * helm_dial_ibeam_create(lv_obj_t * parent, int y,
                                         uint32_t hex)
{
    lv_obj_t * caps = lv_obj_create(parent);
    lv_obj_t * stem;

    lv_obj_remove_style_all(caps);
    lv_obj_set_size(caps, HELM_IBEAM_W, HELM_IBEAM_H);
    lv_obj_set_pos(caps, HELM_SPD_BAR_X - HELM_IBEAM_W / 2, y);
    lv_obj_set_style_bg_opa(caps, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_side(caps,
        LV_BORDER_SIDE_TOP | LV_BORDER_SIDE_BOTTOM, 0);
    lv_obj_set_style_border_width(caps, HELM_IBEAM_CAP, 0);
    lv_obj_set_style_border_color(caps, helm_color(hex), 0);
    lv_obj_set_style_border_opa(caps, LV_OPA_COVER, 0);
    lv_obj_clear_flag(caps, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(caps, LV_OBJ_FLAG_SCROLLABLE);

    stem = lv_obj_create(caps);
    lv_obj_remove_style_all(stem);
    lv_obj_set_size(stem, HELM_IBEAM_STEM, HELM_IBEAM_H);
    lv_obj_align(stem, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(stem, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(stem, helm_color(hex), 0);
    lv_obj_clear_flag(stem, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(stem, LV_OBJ_FLAG_SCROLLABLE);
    return caps;
}

/** @brief 改「工」形滑杆的颜色（横梁 + 竖芯一起；值没变就不碰样式）。 */
static void helm_dial_ibeam_color(lv_obj_t * beam, uint32_t * cur, uint32_t hex)
{
    lv_obj_t * stem;

    if (beam == NULL || cur == NULL || *cur == hex) {
        return;
    }
    *cur = hex;
    lv_obj_set_style_border_color(beam, helm_color(hex), 0);
    stem = lv_obj_get_child(beam, 0);
    if (stem != NULL) {
        lv_obj_set_style_bg_color(stem, helm_color(hex), 0);
    }
